DO $$
DECLARE n int; m int;
BEGIN
  SELECT count(*) INTO n FROM _ca0376_fix;
  IF n <> 100 THEN RAISE EXCEPTION 'pre-flight: expected 100 fix rows, found %', n; END IF;
  SELECT count(*) INTO m FROM inform.politician_context pc JOIN _ca0376_fix f ON f.politician_id = pc.politician_id
   WHERE pc.season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND pc.topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f' AND pc.topic_revision_id = '41349e39-394a-47b9-81c6-a79f8ec60425'
     AND pc.reasoning IN (f.old_text, f.new_text);
  IF m <> 100 THEN RAISE EXCEPTION 'pre-flight: expected 100 rows holding the old or new text, found %', m; END IF;
END $$;

UPDATE inform.politician_context pc SET reasoning = f.new_text, updated_at = now()
  FROM _ca0376_fix f
 WHERE pc.politician_id = f.politician_id AND pc.season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND pc.topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f'
   AND pc.topic_revision_id = '41349e39-394a-47b9-81c6-a79f8ec60425' AND pc.reasoning = f.old_text;

DO $$
DECLARE n int; v int; l int;
BEGIN
  SELECT count(*) INTO n FROM inform.politician_context pc JOIN _ca0376_fix f ON f.politician_id = pc.politician_id
   WHERE pc.season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND pc.topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f' AND pc.topic_revision_id = '41349e39-394a-47b9-81c6-a79f8ec60425' AND pc.reasoning = f.new_text;
  IF n <> 100 THEN RAISE EXCEPTION 'post-verify: expected 100 corrected rows, found %', n; END IF;
  SELECT count(*) INTO v FROM inform.politician_answers pa JOIN _ca0376_fix f ON f.politician_id = pa.politician_id
   WHERE pa.season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND pa.topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f' AND pa.value = f.value;
  IF v <> 100 THEN RAISE EXCEPTION 'post-verify: a seat moved (expected 100 unchanged values), found % matching', v; END IF;
  SELECT count(*) INTO l FROM inform.politician_context pc JOIN _ca0376_fix f ON f.politician_id = pc.politician_id
   WHERE pc.season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND pc.topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f'
     AND pc.reasoning ~ '(^|[^A-Za-z0-9.#-])(R5-(AZ|L)|H12|C2|C37)([^A-Za-z0-9.-]|$)';
  IF l <> 0 THEN RAISE EXCEPTION 'post-verify: % rows still carry an annex label', l; END IF;
END $$;

DROP TABLE _ca0376_fix;
